-- =====================================================================
-- 67 — MANG 96 MÓN TỪ SOURCE SUMO / BUN (sinh bởi tools/port_item_from_sumo.py)
-- =====================================================================
-- 72 cải trang + 24 linh thú. Vật phẩm 2124..2219, part 2370..2657.
--
-- * Ảnh đã chép sẵn vào data/icon/x1..x4; icon nào trùng y hệt ảnh mình đang có thì
--   dùng lại số cũ, còn lại được cấp số mới trong dải trống (trần 32767).
-- * Avatar khung chat lấy từ bảng head_avatar của nguồn; món nào nguồn không có thì
--   tự ghép từ mảnh đầu rồi phóng to.
-- * Linh thú là type 27 có đủ part, đeo ở ô số 7 như các linh thú đã mang về trước đó.
-- * Chưa có chỉ số: phát qua shop / giftcode / cpanel "Buff đồ" rồi thêm option.
--
-- Chạy cùng jar có DataGame.vsItem và vsData đã tăng. Khởi động lại server.
-- Chạy lại nhiều lần vẫn an toàn (tự xoá đúng dải của mình trước khi thêm).
-- TRƯỚC KHI CHẠY: hai câu dưới phải ra 2123 và 2369; khác thì DỪNG, báo lại.
-- =====================================================================
SELECT MAX(`id`) AS item_max FROM `item_template`;
SELECT MAX(`id`) AS part_max FROM `part`;

-- VÀ: bảng item_template KHÔNG được hở id. ItemService.getTemplate(id) lấy theo CHỈ SỐ
-- MẢNG (Manager.ITEM_TEMPLATES.get(id)), hở một id là mọi vật phẩm phía sau lệch hết.
-- Câu dưới phải ra so_dong = so_id = 2124. Lệch thì DỪNG, báo lại trước khi chạy tiếp.
SELECT COUNT(*) AS so_dong, MAX(`id`) + 1 AS so_id FROM `item_template`;

DELETE FROM `item_template` WHERE `id` BETWEEN 2124 AND 2219;
DELETE FROM `part`          WHERE `id` BETWEEN 2370 AND 2657;
DELETE FROM `head_avatar`   WHERE `head_id` BETWEEN 2370 AND 2657;




SELECT `id`, `NAME`, `TYPE`, `icon_id`, `head`, `body`, `leg` FROM `item_template` WHERE `id` BETWEEN 2124 AND 2219;
